  const cinta = new THREE.MeshStandardMaterial({ color: 0xede4d1, roughness: 0.85, metalness: 0 });
  const papel = new THREE.MeshStandardMaterial({ color: 0xf8f8f2, roughness: 0.95, metalness: 0 });
