function centrarYEscalar(obj: THREE.Object3D, objetivo = 2.2) { const caja = new THREE.Box3().setFromObject(obj); if (caja.isEmpty()) return new THREE.Vector3(0, 0, 0); const centro = caja.getCenter(new THREE.Vector3()); const tamano = caja.getSize(new THREE.Vector3()); const mayor = Math.max(tamano.x, tamano.y, tamano.z, 0.001); const escala = objetivo / mayor; obj.scale.setScalar(escala); obj.position.sub(centro.clone().multiplyScalar(escala)); const nueva = new THREE.Box3().setFromObject(obj); return nueva.getCenter(new THREE.Vector3()); }
